def transform(g):
    h,w=len(g),len(g[0])
    div=[j for j in range(w) if len(set(r[j] for r in g))==1]
    d=min(div,key=lambda j:abs(j-w/2))
    left=[r[:d] for r in g]; right=[r[d+1:] for r in g]
    from collections import Counter
    rbg=Counter(v for r in right for v in r).most_common(1)[0][0]
    return [[3 if left[i][j]==right[i][j] else rbg for j in range(len(left[0]))] for i in range(h)]
